package it.unipi.ase.tamers.monsters.catalog;

import com.fasterxml.jackson.core.type.TypeReference;
import com.fasterxml.jackson.databind.DeserializationFeature;
import com.fasterxml.jackson.databind.ObjectMapper;
import com.fasterxml.jackson.databind.PropertyNamingStrategies;
import java.io.IOException;
import java.io.InputStream;
import java.io.UncheckedIOException;
import java.util.ArrayList;
import java.util.HashSet;
import java.util.List;
import java.util.Map;
import java.util.Set;

/** Pure parsing and validation of the seed files (snake_case JSON generated by the monster-gen pipeline). */
public final class SeedData {
    public static final String MONSTERS_RESOURCE = "/seed/monsters.json";
    public static final String ABILITIES_RESOURCE = "/seed/abilities.json";
    public static final String ELEMENTS_RESOURCE = "/seed/elements.json";

    private static final ObjectMapper MAPPER = new ObjectMapper()
            .setPropertyNamingStrategy(PropertyNamingStrategies.SNAKE_CASE)
            .configure(DeserializationFeature.FAIL_ON_UNKNOWN_PROPERTIES, false);

    private SeedData() {}

    public record SeedMonster(int monsterId, String name, String element, String rarity, String description,
                              String imageUrl, int baseHp, int baseAttack, int baseDefense, int baseSpeed,
                              double growthHp, double growthAttack, double growthDefense, double growthSpeed,
                              int abilityId) {}

    public record SeedAbility(int abilityId, String name, String scope, String element, String effectType,
                              int effectValue, String trigger, String description) {}

    public static List<SeedMonster> readMonsters(InputStream in) {
        return read(in, new TypeReference<List<SeedMonster>>() {});
    }

    public static List<SeedAbility> readAbilities(InputStream in) {
        return read(in, new TypeReference<List<SeedAbility>>() {});
    }

    public static ElementCycle readElements(InputStream in) {
        return read(in, new TypeReference<ElementCycle>() {});
    }

    public static InputStream open(String resource) {
        InputStream in = SeedData.class.getResourceAsStream(resource);
        if (in == null) {
            throw new IllegalStateException("seed file not found on the classpath: " + resource);
        }
        return in;
    }

    private static <T> T read(InputStream in, TypeReference<T> type) {
        try (in) {
            return MAPPER.readValue(in, type);
        } catch (IOException e) {
            throw new UncheckedIOException("cannot parse seed file", e);
        }
    }

    /** Returns a list of human-readable problems; empty when the seed is consistent. */
    public static List<String> validate(List<SeedMonster> monsters, List<SeedAbility> abilities, ElementCycle cycle) {
        List<String> problems = new ArrayList<>();
        Set<Integer> abilityIds = new HashSet<>();
        for (SeedAbility a : abilities) {
            if (!abilityIds.add(a.abilityId())) {
                problems.add("duplicate ability_id " + a.abilityId());
            }
            if (a.element() != null && !isElement(a.element())) {
                problems.add("ability " + a.abilityId() + " has unknown element " + a.element());
            }
        }
        Set<Integer> monsterIds = new HashSet<>();
        Set<String> names = new HashSet<>();
        for (SeedMonster m : monsters) {
            if (!monsterIds.add(m.monsterId())) {
                problems.add("duplicate monster_id " + m.monsterId());
            }
            if (!names.add(m.name())) {
                problems.add("duplicate monster name " + m.name());
            }
            if (!isElement(m.element())) {
                problems.add("monster " + m.monsterId() + " has unknown element " + m.element());
            }
            if (!isRarity(m.rarity())) {
                problems.add("monster " + m.monsterId() + " has unknown rarity " + m.rarity());
            }
            if (!abilityIds.contains(m.abilityId())) {
                problems.add("monster " + m.monsterId() + " references missing ability " + m.abilityId());
            }
        }
        for (Element e : Element.values()) {
            if (!cycle.cycle().contains(e.value()) || cycle.strongOf(e.value()) == null
                    || cycle.weakOf(e.value()) == null) {
                problems.add("element cycle is incomplete for " + e.value());
            }
        }
        return problems;
    }

    private static boolean isElement(String value) {
        for (Element e : Element.values()) {
            if (e.value().equals(value)) return true;
        }
        return false;
    }

    private static boolean isRarity(String value) {
        for (Rarity r : Rarity.values()) {
            if (r.value().equals(value)) return true;
        }
        return false;
    }

    /** Element interactions as in {@code seed/elements.json}. */
    public record ElementCycle(List<String> cycle, Map<String, String> strongAgainst, Map<String, String> weakAgainst) {
        public String strongOf(String element) {
            return strongAgainst.get(element);
        }

        public String weakOf(String element) {
            return weakAgainst.get(element);
        }
    }
}
